/**
 * Webhook endpoints and their delivery attempts.
 */
import { and, asc, count, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, webhookDeliveries, webhookEndpoints } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import type { CreateWebhookInput, UpdateWebhookInput } from "@/schemas/webhook";
import type {
  WebhookDeliveryRow,
  WebhookEndpointRow,
} from "@/server/db/schema/webhooks";
import type { IsoTimestamp, OrgId, WebhookId } from "@/types/common";

export async function listEndpoints(
  orgId: OrgId,
): Promise<readonly WebhookEndpointRow[]> {
  return getDb()
    .select()
    .from(webhookEndpoints)
    .where(orgPredicate(webhookEndpoints.orgId, orgId))
    .orderBy(asc(webhookEndpoints.createdAt))
    .all();
}

export async function insertEndpoint(
  input: CreateWebhookInput,
  secret: string,
): Promise<WebhookEndpointRow> {
  const stamp = toIsoTimestamp(new Date());
  return getDb()
    .insert(webhookEndpoints)
    .values({
      id: newId(),
      orgId: input.orgId,
      url: input.url,
      secret,
      eventTypes: JSON.stringify(input.eventTypes),
      enabled: true,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
}

export async function updateEndpoint(
  input: UpdateWebhookInput,
): Promise<WebhookEndpointRow> {
  const row = getDb()
    .update(webhookEndpoints)
    .set({
      ...(input.url === undefined ? {} : { url: input.url }),
      ...(input.eventTypes === undefined
        ? {}
        : { eventTypes: JSON.stringify(input.eventTypes) }),
      ...(input.enabled === undefined ? {} : { enabled: input.enabled }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(webhookEndpoints.orgId, input.orgId),
        eq(webhookEndpoints.id, input.webhookId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Webhook ${input.webhookId} not found`);
  return row;
}

export async function deleteEndpoint(
  orgId: OrgId,
  webhookId: WebhookId,
): Promise<void> {
  const db = getDb();
  db.delete(webhookDeliveries)
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.endpointId, webhookId),
      ),
    )
    .run();
  db.delete(webhookEndpoints)
    .where(
      and(
        orgPredicate(webhookEndpoints.orgId, orgId),
        eq(webhookEndpoints.id, webhookId),
      ),
    )
    .run();
}

/** The `webhooks` quota compares against this. */
export async function countEndpoints(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(webhookEndpoints)
    .where(orgPredicate(webhookEndpoints.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

export async function enqueueDelivery(
  orgId: OrgId,
  endpointId: string,
  eventType: string,
  payload: string,
): Promise<WebhookDeliveryRow> {
  const stamp = toIsoTimestamp(new Date());
  return getDb()
    .insert(webhookDeliveries)
    .values({
      id: newId(),
      orgId,
      endpointId,
      eventType,
      payload,
      status: "pending",
      attempts: 0,
      lastError: null,
      deliveredAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
}

/**
 * Claims a batch for the delivery job. Cross-tenant on purpose — the queue is
 * drained by a background worker, not by a request — and the attempt counter
 * is bumped on claim so a crashed worker cannot retry forever.
 */
export async function claimPendingDeliveries(
  limit: number,
): Promise<readonly WebhookDeliveryRow[]> {
  const db = getDb();
  const pending = db
    .select()
    .from(webhookDeliveries)
    .where(eq(webhookDeliveries.status, "pending"))
    .orderBy(asc(webhookDeliveries.createdAt))
    .limit(Math.max(1, limit))
    .all();

  return pending.map((row) =>
    db
      .update(webhookDeliveries)
      .set({
        attempts: row.attempts + 1,
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(eq(webhookDeliveries.id, row.id))
      .returning()
      .get(),
  );
}

export async function markDelivered(
  orgId: OrgId,
  deliveryId: string,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(webhookDeliveries)
    .set({ status: "delivered", deliveredAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.id, deliveryId),
      ),
    )
    .run();
}

export async function markDeliveryFailed(
  orgId: OrgId,
  deliveryId: string,
  error: string,
): Promise<void> {
  getDb()
    .update(webhookDeliveries)
    .set({
      status: "failed",
      lastError: error.slice(0, 500),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.id, deliveryId),
      ),
    )
    .run();
}
/**
 * Slug generation and validation, shared by organization creation, project
 * creation and the "is this slug free?" checks in both the Zod schemas and the
 * repositories. One implementation so the client preview and the server
 * insertion can never disagree.
 */

export const SLUG_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

export const SLUG_MIN_LENGTH = 2;
export const SLUG_MAX_LENGTH = 48;

/** Slugs the router or marketing pages already claim. */
export const RESERVED_SLUGS: readonly string[] = [
  "admin",
  "api",
  "auth",
  "billing",
  "blog",
  "changelog",
  "dashboard",
  "docs",
  "help",
  "login",
  "logout",
  "new",
  "pricing",
  "register",
  "settings",
  "static",
  "support",
  "taskflow",
  "www",
];

/** Lowercases, strips diacritics and punctuation, collapses to `a-z0-9-`. */
export function slugify(input: string): string {
  return input
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, SLUG_MAX_LENGTH)
    .replace(/-+$/g, "");
}

export function isValidSlug(value: string): boolean {
  return (
    value.length >= SLUG_MIN_LENGTH &&
    value.length <= SLUG_MAX_LENGTH &&
    SLUG_PATTERN.test(value)
  );
}

export function isReservedSlug(value: string): boolean {
  return RESERVED_SLUGS.includes(value);
}

export class InvalidSlugError extends Error {
  readonly code = "validation_failed" as const;

  constructor(readonly value: string, readonly reason: string) {
    super(`Invalid slug "${value}": ${reason}`);
    this.name = "InvalidSlugError";
  }
}

export function assertValidSlug(value: string): void {
  if (!isValidSlug(value)) {
    throw new InvalidSlugError(value, "must match ^[a-z0-9]+(-[a-z0-9]+)*$");
  }
  if (isReservedSlug(value)) {
    throw new InvalidSlugError(value, "is reserved");
  }
}

/**
 * Derives a slug from `input` that collides with nothing in `taken`, by
 * appending `-2`, `-3`, … Repositories pass their existing slug set in.
 */
export function uniqueSlug(input: string, taken: Iterable<string>): string {
  const base = slugify(input) || "item";
  const used = new Set(taken);
  if (!used.has(base) && !isReservedSlug(base)) return base;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const candidate = `${base.slice(0, SLUG_MAX_LENGTH - 5)}-${suffix}`;
    if (!used.has(candidate) && !isReservedSlug(candidate)) return candidate;
  }
  throw new InvalidSlugError(base, "exhausted unique suffixes");
}

/** Project keys are the short uppercase prefix shown on issue numbers (TF-12). */
export function projectKeyFromName(name: string): string {
  const words = name.trim().split(/\s+/).filter(Boolean);
  const letters =
    words.length >= 2
      ? words.slice(0, 3).map((w) => w[0] ?? "").join("")
      : (words[0] ?? "task").slice(0, 3);
  return letters.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 4) || "TASK";
}

